CREATE OR REPLACE FUNCTION recoveryos.acknowledge_document(p_assignment_id bigint, p_signature_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'recoveryos', 'public'
AS $function$
declare
  v_me bigint := recoveryos.current_person_id();
  v_a recoveryos.document_assignments%rowtype;
  v_requires_signature boolean;
  v_version text;
  v_hash text;
begin
  if v_me is null then return jsonb_build_object('ok', false, 'code', 'unauthenticated'); end if;
  select * into v_a from recoveryos.document_assignments where id = p_assignment_id for update;
  if not found then return jsonb_build_object('ok', false, 'code', 'not_found'); end if;
  if v_a.person_id <> v_me then
    return jsonb_build_object('ok', false, 'code', 'not_authorized',
      'message', 'Only the person a document is assigned to may acknowledge it.');
  end if;
  if v_a.acknowledged_at is not null then
    return jsonb_build_object('ok', true, 'code', 'already_acknowledged');
  end if;

  select t.requires_signature, dv.version, dv.content_hash
    into v_requires_signature, v_version, v_hash
  from recoveryos.document_versions dv
  join recoveryos.document_templates t on t.id = dv.template_id
  where dv.id = v_a.document_version_id;

  if v_requires_signature then
    if not exists (
      select 1 from recoveryos.consent_grants g
      join recoveryos.consent_types ct on ct.id = g.consent_type_id
      where g.person_id = v_me and ct.key = 'electronic_records'
        and g.status = 'granted' and g.revoked_at is null
        and (g.expires_at is null or g.expires_at > now())) then
      return jsonb_build_object('ok', false, 'code', 'electronic_consent_required',
        'message', 'Electronic signing needs your electronic-records consent first — or sign on paper with staff.');
    end if;
    if p_signature_name is null or length(trim(p_signature_name)) < 2
       or length(p_signature_name) > 200 then
      return jsonb_build_object('ok', false, 'code', 'signature_name_required',
        'message', 'Type your name to sign this document.');
    end if;
    update recoveryos.document_assignments
       set acknowledged_at = now(), signed_at = now(), signature_name = trim(p_signature_name),
           signature_method = 'electronic'
     where id = p_assignment_id;
  else
    update recoveryos.document_assignments
       set acknowledged_at = now()
     where id = p_assignment_id;
  end if;

  insert into recoveryos.audit_log (actor_person_id, action, entity_table, entity_id, detail)
  values (v_me,
          case when v_requires_signature then 'document_signed' else 'document_acknowledged' end,
          'document_assignments', p_assignment_id,
          jsonb_build_object('document_version_id', v_a.document_version_id,
                             'version', v_version, 'content_hash', v_hash,
                             'signature_method', case when v_requires_signature then 'electronic' end));

  return jsonb_build_object('ok', true,
    'code', case when v_requires_signature then 'signed' else 'acknowledged' end,
    'content_hash', v_hash);
end $function$

CREATE OR REPLACE FUNCTION recoveryos.application_intake_readiness(p_application_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'recoveryos', 'public'
AS $function$
declare
  v_me bigint := recoveryos.current_person_id();
  v_app recoveryos.residence_applications%rowtype;
  v_items jsonb := '[]'::jsonb;
  v_blocking jsonb;
  v_t record;
  v_met boolean;
  v_reviewed_none boolean;
  v_sig_count int := 0;
  v_has_screening boolean;
  v_supervision_applies boolean;
  v_accommodation_raised boolean;
begin
  if v_me is null then return jsonb_build_object('ok', false, 'code', 'unauthenticated'); end if;
  select * into v_app from recoveryos.residence_applications where id = p_application_id;
  if not found then return jsonb_build_object('ok', false, 'code', 'not_found'); end if;
  if v_app.person_id <> v_me
     and v_app.residence_id not in (select recoveryos.staff_residence_ids())
     and not recoveryos.is_care_operations_staff()
     and not recoveryos.is_platform_admin() then
    return jsonb_build_object('ok', false, 'code', 'not_authorized');
  end if;

  for v_t in
    select t.key, t.name
    from recoveryos.document_templates t
    join recoveryos.residences r on r.id = v_app.residence_id
     and r.organization_id = t.organization_id
    where t.is_active and t.requires_signature
      and (t.residence_id is null or t.residence_id = v_app.residence_id)
      and exists (select 1 from recoveryos.document_versions dv
                  where dv.template_id = t.id and dv.published_at is not null)
    order by t.key
  loop
    v_sig_count := v_sig_count + 1;
    select exists (
      select 1 from recoveryos.document_assignments a
      join recoveryos.document_versions dv on dv.id = a.document_version_id
      join recoveryos.document_templates t2 on t2.id = dv.template_id
      where a.person_id = v_app.person_id and t2.key = v_t.key and a.signed_at is not null
    ) into v_met;
    v_items := v_items || jsonb_build_object(
      'key', 'sign:' || v_t.key, 'label', 'Sign: ' || v_t.name,
      'class', 'required_before_admission',
      'status', case when v_met then 'met' else 'missing' end,
      'met', v_met, 'overridable', false);
  end loop;

  if v_sig_count = 0 then
    v_items := v_items || jsonb_build_object(
      'key', 'signature_documents', 'label', 'Residence document edition (signature set)',
      'class', 'required_before_admission',
      'status', 'pending_document_edition',
      'met', false, 'overridable', false);
  end if;

  for v_t in
    select t.key, t.name
    from recoveryos.document_templates t
    join recoveryos.residences r on r.id = v_app.residence_id
     and r.organization_id = t.organization_id
    where t.is_active and t.requires_acknowledgment and not t.requires_signature
      and (t.residence_id is null or t.residence_id = v_app.residence_id)
      and exists (select 1 from recoveryos.document_versions dv
                  where dv.template_id = t.id and dv.published_at is not null)
    order by t.key
  loop
    select exists (
      select 1 from recoveryos.document_assignments a
      join recoveryos.document_versions dv on dv.id = a.document_version_id
      join recoveryos.document_templates t2 on t2.id = dv.template_id
      where a.person_id = v_app.person_id and t2.key = v_t.key and a.acknowledged_at is not null
    ) into v_met;
    v_items := v_items || jsonb_build_object(
      'key', 'ack:' || v_t.key, 'label', 'Acknowledge: ' || v_t.name,
      'class', 'required_for_intake_completion',
      'status', case when v_met then 'met' else 'missing' end,
      'met', v_met, 'overridable', false);
  end loop;

  select exists (
    select 1 from recoveryos.consent_grants g
    join recoveryos.consent_types ct on ct.id = g.consent_type_id
    where g.person_id = v_app.person_id and ct.key = 'residence_screening'
      and g.status = 'granted' and g.revoked_at is null
      and (g.expires_at is null or g.expires_at > now())
  ) into v_has_screening;
  v_items := v_items || jsonb_build_object(
    'key', 'screening_consent', 'label', 'Screening consent (current grant)',
    'class', 'required_before_admission',
    'status', case when v_has_screening then 'met' else 'missing' end,
    'met', v_has_screening, 'overridable', false);

  select exists (
    select 1 from recoveryos.emergency_contacts c
    where c.person_id = v_app.person_id and c.is_active
  ) into v_met;
  v_items := v_items || jsonb_build_object(
    'key', 'emergency_contact', 'label', 'Emergency contact on file',
    'class', 'required_for_intake_completion',
    'status', case when v_met then 'met' else 'missing' end,
    'met', v_met, 'overridable', false);

  select exists (
    select 1 from recoveryos.residency_medication_items m
    where m.person_id = v_app.person_id and m.ended_at is null
  ) into v_met;
  select exists (
    select 1 from recoveryos.medication_status_reviews
    where person_id = v_app.person_id and superseded_at is null
  ) into v_reviewed_none;
  v_items := v_items || jsonb_build_object(
    'key', 'medication_items', 'label', 'Medication status reviewed per medication policy',
    'class', 'conditionally_required',
    'status', case when v_met then 'met'
                   when v_reviewed_none then 'reviewed_none'
                   else 'unconfirmed' end,
    'met', v_met or v_reviewed_none, 'overridable', true);

  v_accommodation_raised := nullif(trim(coalesce(v_app.answers->>'accommodation_needs','')), '') is not null;
  if v_accommodation_raised then
    v_items := v_items || jsonb_build_object(
      'key', 'accommodation', 'label', 'Accommodation need reviewed with staff',
      'class', 'conditionally_required',
      'status', 'needs_staff_review', 'met', false, 'overridable', true);
  else
    v_items := v_items || jsonb_build_object(
      'key', 'accommodation', 'label', 'Accommodation need reviewed with staff',
      'class', 'not_applicable', 'status', 'not_applicable',
      'met', true, 'overridable', false);
  end if;

  v_supervision_applies := lower(coalesce(v_app.answers->>'supervision_coordination','')) = 'yes';
  if v_supervision_applies then
    select exists (
      select 1 from recoveryos.supervision_coordination_records s
      join recoveryos.consent_grants g on g.id = s.consent_grant_id
      where s.person_id = v_app.person_id and s.is_active
        and g.status = 'granted' and g.revoked_at is null
        and (g.expires_at is null or g.expires_at > now())
    ) into v_met;
    v_items := v_items || jsonb_build_object(
      'key', 'supervision', 'label', 'Supervision coordination authorized + contact on file',
      'class', 'conditionally_required',
      'status', case when v_met then 'met' else 'missing' end,
      'met', v_met, 'overridable', true);
  else
    v_items := v_items || jsonb_build_object(
      'key', 'supervision', 'label', 'Supervision coordination authorized + contact on file',
      'class', 'not_applicable', 'status', 'not_applicable',
      'met', true, 'overridable', false);
  end if;

  select coalesce(jsonb_agg(i->>'key'), '[]'::jsonb) into v_blocking
  from jsonb_array_elements(v_items) i
  where (i->>'met')::boolean = false;

  return jsonb_build_object('ok', true,
    'application_id', p_application_id,
    'complete', jsonb_array_length(v_blocking) = 0,
    'items', v_items,
    'blocking_unmet', v_blocking);
end $function$

CREATE OR REPLACE FUNCTION recoveryos.ensure_my_document_assignments()
 RETURNS SETOF recoveryos.document_assignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'recoveryos', 'public'
AS $function$
declare
  v_person_id bigint := recoveryos.current_person_id();
  v_residency recoveryos.residencies%rowtype;
  v_app recoveryos.residence_applications%rowtype;
  v_residence_id bigint;
  v_residency_id bigint;
  v_application_id bigint;
begin
  if v_person_id is null then
    raise exception 'Not authenticated';
  end if;

  select * into v_residency
  from recoveryos.residencies
  where person_id = v_person_id
    and residency_status in ('active', 'on_pass', 'transitioning')
  order by created_at desc
  limit 1;

  if found then
    v_residence_id := v_residency.residence_id;
    v_residency_id := v_residency.id;
  else
    -- Intake stage: an approved application unlocks the document set pre-admission.
    select * into v_app
    from recoveryos.residence_applications
    where person_id = v_person_id and status = 'approved'
    order by submitted_at desc
    limit 1;
    if found then
      v_residence_id := v_app.residence_id;
      v_application_id := v_app.id;
    end if;
  end if;

  if v_residence_id is not null then
    insert into recoveryos.document_assignments
      (document_version_id, person_id, residency_id, application_id)
    select dv.id, v_person_id, v_residency_id, v_application_id
    from recoveryos.document_templates t
    join recoveryos.residences r on r.id = v_residence_id
      and r.organization_id = t.organization_id
    join lateral (
      select id from recoveryos.document_versions
      where template_id = t.id and published_at is not null
      order by published_at desc
      limit 1
    ) dv on true
    where t.is_active
      and (t.requires_signature or t.requires_acknowledgment)
      and (t.residence_id is null or t.residence_id = v_residence_id)
      and not exists (
        select 1 from recoveryos.document_assignments a
        where a.person_id = v_person_id and a.document_version_id = dv.id
      );
  end if;

  return query
  select * from recoveryos.document_assignments where person_id = v_person_id;
end;
$function$

CREATE OR REPLACE FUNCTION recoveryos.record_paper_signature(p_person_id bigint, p_template_key text, p_signature_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'recoveryos', 'public'
AS $function$
declare
  v_me bigint := recoveryos.current_person_id();
  v_a recoveryos.document_assignments%rowtype;
  v_version text;
  v_hash text;
begin
  if v_me is null then return jsonb_build_object('ok', false, 'code', 'unauthenticated'); end if;
  if not recoveryos.is_platform_admin() and not exists (
       select 1 from recoveryos.residencies r
       where r.person_id = p_person_id
         and r.residence_id in (select recoveryos.staff_residence_ids())
       union all
       select 1 from recoveryos.residence_applications a
       where a.person_id = p_person_id
         and a.residence_id in (select recoveryos.staff_residence_ids())) then
    return jsonb_build_object('ok', false, 'code', 'not_authorized');
  end if;
  if p_signature_name is null or length(trim(p_signature_name)) < 2
     or length(p_signature_name) > 200 then
    return jsonb_build_object('ok', false, 'code', 'signature_name_required');
  end if;

  select a.* into v_a
  from recoveryos.document_assignments a
  join recoveryos.document_versions dv on dv.id = a.document_version_id
  join recoveryos.document_templates t on t.id = dv.template_id
  where a.person_id = p_person_id and t.key = p_template_key
    and t.requires_signature and a.acknowledged_at is null
  order by a.assigned_at desc
  limit 1
  for update of a;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'no_pending_assignment',
      'message', 'No unsigned signature assignment for that document.');
  end if;

  select dv.version, dv.content_hash into v_version, v_hash
  from recoveryos.document_versions dv where dv.id = v_a.document_version_id;

  update recoveryos.document_assignments
     set acknowledged_at = now(), signed_at = now(), signature_name = trim(p_signature_name),
         signature_method = 'paper'
   where id = v_a.id;

  insert into recoveryos.audit_log (actor_person_id, action, entity_table, entity_id, detail)
  values (v_me, 'document_signed_paper', 'document_assignments', v_a.id,
          jsonb_build_object('person_id', p_person_id,
                             'document_version_id', v_a.document_version_id,
                             'version', v_version, 'content_hash', v_hash,
                             'signature_method', 'paper', 'witnessed_by_person_id', v_me));

  return jsonb_build_object('ok', true, 'code', 'signed_paper', 'content_hash', v_hash);
end $function$

CREATE OR REPLACE FUNCTION recoveryos.trg_document_assignments_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'recoveryos', 'public'
AS $function$
begin
  if tg_op = 'DELETE' then
    if old.acknowledged_at is not null then
      raise exception 'acknowledged document assignments are immutable evidence';
    end if;
    return old;
  end if;
  if old.acknowledged_at is not null then
    raise exception 'acknowledged document assignments are immutable evidence';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION recoveryos.trg_document_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'recoveryos', 'public'
AS $function$
declare
  v_key text;
  v_residence_id bigint;
begin
  if new.acknowledged_at is null or old.acknowledged_at is not null then
    return new;
  end if;
  select t.key into v_key
  from document_versions dv join document_templates t on t.id = dv.template_id
  where dv.id = new.document_version_id;
  select residence_id into v_residence_id from residencies where id = new.residency_id;
  if v_residence_id is null then
    return new;
  end if;

  if v_key = 'participant_agreement' then
    perform narr_auto_evidence(v_residence_id, '1.B.5.a', 'Auto: Participant Agreement signed (assignment #' || new.id || ')');
    perform narr_auto_evidence(v_residence_id, '1.A.2.d', 'Auto: non-discrimination terms acknowledged via Participant Agreement');
  elsif v_key = 'fee_schedule_financial_agreement' then
    perform narr_auto_evidence(v_residence_id, '1.A.3.a', 'Auto: Fee Schedule acknowledged before funds accepted (assignment #' || new.id || ')');
    perform narr_auto_evidence(v_residence_id, '1.A.3.c', 'Auto: refund terms acknowledged via Fee Schedule & Financial Agreement');
  elsif v_key = 'code_of_conduct' then
    perform narr_auto_evidence(v_residence_id, '2.F.16.a', 'Auto: substance-free policy acknowledged via Code of Conduct');
    perform narr_auto_evidence(v_residence_id, '1.B.6.c', 'Auto: social media privacy standards acknowledged via Code of Conduct');
  elsif v_key = 'resident_handbook' then
    perform narr_auto_evidence(v_residence_id, '1.C.7.c', 'Auto: resident rights provided and acknowledged via Handbook');
  elsif v_key = 'medication_mat_moud_policy' then
    perform narr_auto_evidence(v_residence_id, '2.F.16.d', 'Auto: medication storage policy acknowledged');
  elsif v_key = 'good_neighbor_policy' then
    perform narr_auto_evidence(v_residence_id, '4.J.30.c', 'Auto: neighbor interaction orientation acknowledged');
  end if;
  return new;
end;
$function$
